{"content":"#!/usr/bin/env python3
import sys
import re

def normalize_path(path):
    # Extract path variable pattern: { followed by alphanumeric, underscores, hyphens, followed by }
    # Replace valid path variable patterns with {var}
    return re.sub(r'\{[a-zA-Z0-9_-]+\}', '{var}', path)

def count_segments(path):
    return len([s for s in path.split('/') if s])

def parse_input(file_path):
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    section = 1
    endpoints_raw_lines = []
    base_exclude_raw_lines = []
    plan_raw_lines = []

    for line in lines:
        stripped = line.strip()
        if stripped == '':
            if section == 1 and endpoints_raw_lines:
                section = 2
            elif section == 2 and base_exclude_raw_lines:
                section = 3
            elif section == 1:
                section = 2
            elif section == 2:
                section = 3
            continue

        if section == 1:
            endpoints_raw_lines.append(line)
        elif section == 2:
            parts = stripped.split()
            if parts and parts[0] in ('base', 'exclude'):
                base_exclude_raw_lines.append(line)
            else:
                section = 3
                plan_raw_lines.append(line)
        elif section == 3:
            plan_raw_lines.append(line)

    # 1. Parse ENDPOINTS
    endpoints = []
    cutoff = False
    valid_methods = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
    valid_perms = {'ALLOW', 'DENY'}

    for line in endpoints_raw_lines:
        if cutoff:
            break
        fields = line.strip().split()
        if len(fields) != 4:
            cutoff = True
            break
        path, method, role, perm = fields
        path = path.strip()
        role = role.strip()
        method = method.strip().upper()
        perm = perm.strip().upper()

        if not path or not role or method not in valid_methods or perm not in valid_perms:
            cutoff = True
            break

        endpoints.append({
            'orig_path': path,
            'method': method,
            'role': role,
            'permission': perm
        })

    # Deduplicate and record first encountered original path variable names
    canonical_orig_paths = {}
    dedup_endpoints = []
    seen_tuples = set()

    for ep in endpoints:
        norm_p = normalize_path(ep['orig_path'])
        if norm_p not in canonical_orig_paths:
            canonical_orig_paths[norm_p] = ep['orig_path']

        tuple_key = (norm_p, ep['method'], ep['role'])
        if tuple_key not in seen_tuples:
            seen_tuples.add(tuple_key)
            dedup_endpoints.append({
                'norm_path': norm_p,
                'method': ep['method'],
                'role': ep['role'],
                'permission': ep['permission']
            })

    # 2. Parse BASE / EXCLUDE
    base_path = None
    exclude_roles = set()

    for line in base_exclude_raw_lines:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == 'base':
            if len(parts) >= 2:
                base_path = parts[1].strip()
        elif parts[0] == 'exclude':
            for r in parts[1:]:
                r_str = r.strip()
                if r_str:
                    exclude_roles.add(r_str)

    # 3. Parse PLAN
    plan_items = []
    plan_cutoff = False

    for line in plan_raw_lines:
        if plan_cutoff:
            break
        fields = line.strip().split()
        if len(fields) != 2:
            plan_cutoff = True
            break
        path, method = fields
        path = path.strip()
        method = method.strip().upper()

        if not path or method not in valid_methods:
            plan_cutoff = True
            break

        norm_p = normalize_path(path)
        plan_items.append((norm_p, method))

    return dedup_endpoints, canonical_orig_paths, base_path, exclude_roles, plan_items

def process():
    dedup_endpoints, canonical_orig_paths, base_path, exclude_roles, plan_items = parse_input('/app/input.txt')

    # Filter by base
    norm_base = normalize_path(base_path) if base_path else None

    def matches_base(ep):
        if norm_base is None:
            return True
        return ep['norm_path'].startswith(norm_base)

    base_eligible = [ep for ep in dedup_endpoints if matches_base(ep)]

    # Filter by exclude (eligible non-excluded endpoints)
    valid_eligible = [ep for ep in base_eligible if ep['role'] not in exclude_roles]

    if not plan_items:
        # PLAN is empty: output all valid eligible endpoints
        final_endpoints = valid_eligible
    else:
        # PLAN is specified
        plan_set = set(plan_items)

        # Target endpoints in PLAN
        target_endpoints = [ep for ep in valid_eligible if (ep['norm_path'], ep['method']) in plan_set]

        # Selected endpoints dictionary to ensure uniqueness by (norm_path, method, role)
        selected_map = {}
        for ep in target_endpoints:
            key = (ep['norm_path'], ep['method'], ep['role'])
            selected_map[key] = ep

        # Parent path resolution for target endpoints
        all_base_norm_paths = set(ep['norm_path'] for ep in base_eligible)

        for target_ep in target_endpoints:
            target_norm = target_ep['norm_path']
            target_segs = [s for s in target_norm.split('/') if s]

            for cand_norm in all_base_norm_paths:
                cand_segs = [s for s in cand_norm.split('/') if s]
                # Check if cand_norm is a parent path
                if len(cand_segs) < len(target_segs) and cand_segs == target_segs[:len(cand_segs)]:
                    cand_eps = [ep for ep in base_eligible if ep['norm_path'] == cand_norm]
                    cand_valid = [ep for ep in cand_eps if ep['role'] not in exclude_roles]

                    if cand_valid:
                        for ep in cand_valid:
                            key = (ep['norm_path'], ep['method'], ep['role'])
                            selected_map[key] = ep
                    elif cand_eps:
                        # Only excluded endpoints exist for this parent path
                        for ep in cand_eps:
                            key = (ep['norm_path'], ep['method'], ep['role'])
                            selected_map[key] = ep

        final_endpoints = list(selected_map.values())

    if not final_endpoints:
        with open('/app/output.txt', 'w', encoding='utf-8') as f:
            f.write('\n')
        return

    # Sort final endpoints
    # 1. Segment count (longer first)
    # 2. Path string (canonical original path)
    # 3. Method (alphabetical: DELETE, GET, PATCH, POST, PUT)
    # 4. Role (lexicographic)
    # 5. Permission (ALLOW before DENY)
    def sort_key(ep):
        orig_p = canonical_orig_paths[ep['norm_path']]
        seg_cnt = count_segments(orig_p)
        return (-seg_cnt, orig_p, ep['method'], ep['role'], ep['permission'])

    final_endpoints.sort(key=sort_key)

    lines = []
    for ep in final_endpoints:
        orig_p = canonical_orig_paths[ep['norm_path']]
        lines.append(f"{orig_p} {ep['method']} {ep['role']} {ep['permission']}")

    with open('/app/output.txt', 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines) + '\n')

if __name__ == '__main__':
    process()
